  <aside t-if=\"hasLeftColumn\" id=\"products_grid_before\" class=\"d-none d-lg-block position-sticky col-3 px-3 clearfix\">\n\n                        <div class=\"o_wsale_products_grid_before_rail vh-100 ms-n2 mt-n2 pt-2 pe-lg-2 pb-lg-5 ps-2 overflow-y-scroll\">\n\n                            <div t-if=\"opt_wsale_categories\" class=\"products_categories mb-3\">\n                                <t t-call=\"website_sale.products_categories_list\"/>\n                            </div>\n\n                            <div class=\"products_attributes_filters\"/>\n\n                            <t t-if=\"opt_wsale_filter_price and opt_wsale_attributes\" t-call=\"website_sale.filter_products_price\"/>\n\n                        </div>\n                    </aside>\n\n                    <div id=\"products_grid\" t-attf-class=\"#{'o_wsale_layout_list' if layout_mode == 'list' else ''} {{'col-lg-9' if hasLeftColumn else 'col-12'}}\">\n\n                        <t t-call=\"website_sale.products_breadcrumb\">\n                            <t t-set=\"_classes\" t-valuef=\"d-none d-lg-flex w-100 p-0 small\"/>\n                        </t>\n\n                        <div class=\"products_header btn-toolbar flex-nowrap align-items-center justify-content-between gap-3 mb-3\">\n\n                            <t t-if=\"is_view_active('website_sale.search')\" t-call=\"website_sale.search\">\n\n                                <t t-set=\"search\" t-value=\"original_search or search\"/>\n\n                                <t t-set=\"_form_classes\" t-valuef=\"d-lg-inline {{'d-inline' if not category else 'd-none'}}\"/>\n                            </t>\n\n                            <t t-call=\"website_sale.pricelist_list\" t-cache=\"pricelist\">\n\n                                <t t-set=\"_classes\" t-valuef=\"d-none d-lg-inline\"/>\n                            </t>\n\n                            <t t-if=\"is_view_active('website_sale.sort')\" t-call=\"website_sale.sort\">\n\n                                <t t-set=\"_classes\" t-valuef=\"d-none me-auto d-lg-inline-block\"/>\n                            </t>\n\n                            <div t-if=\"category\" class=\"d-flex align-items-center d-lg-none me-auto\">\n\n                                <t t-if=\"not category.parent_id\" t-set=\"backUrl\" t-valuef=\"/shop\"/>\n\n                                <t t-else=\"\" t-set=\"backUrl\" t-value=\"keep('/shop/category/' + slug(category.parent_id), category=0)\"/>\n\n                                <a t-attf-class=\"btn btn-{{navClass}} me-2\" t-att-href=\"category.parent_id and keep('/shop/category/' + slug(category.parent_id), category=0) or '/shop'\">\n\n                                    <i class=\"fa fa-angle-left\"/>\n                                </a>\n\n                                <h4 t-out=\"category.name\" class=\"mb-0 me-auto\"/>\n                            </div>\n\n                            \n\n                            <button t-if=\"is_view_active('website_sale.sort') or opt_wsale_categories or opt_wsale_attributes or opt_wsale_attributes_top\" t-attf-class=\"btn btn-{{navClass}} position-relative {{not opt_wsale_attributes_top and 'd-lg-none'}}\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#o_wsale_offcanvas\">\n\n                                <i class=\"fa fa-sliders\"/>\n\n                                <span t-if=\"isFilteringByPrice or attrib_set or tags\" t-attf-class=\"position-absolute top-0 start-100 translate-middle border border-{{navClass}} rounded-circle bg-danger p-1\">\n\n                                    <span class=\"visually-hidden\">\n                                        filtros activos\n                                    </span>\n                                </span>\n                            </button>\n\n                        </div>\n\n                        <t t-if=\"opt_wsale_categories_top\" t-call=\"website_sale.filmstrip_categories\"/>\n\n                        <div t-if=\"original_search and products\" class=\"alert alert-warning mt8\">\n\n                            No se han encontrado resultados para\n                            \"<span t-esc=\"original_search\"/>\".\n                            Mostrando resultados para\n                            \"<span t-esc=\"search\"/>\".\n                        </div>\n\n                        <t t-if=\"category\">\n\n                            <t t-set=\"editor_msg\">\n                                Mueva componentes aquí para personalizar el\n                                encabezado de \"<t t-esc=\"category.name\"/>\"\n                                como categoría.\n                            </t>\n\n                            <div class=\"mb16\" id=\"category_header\" t-att-data-editor-message=\"editor_msg\" t-field=\"category.website_description\"/>\n                        </t>\n\n                        <div t-if=\"products\" class=\"o_wsale_products_grid_table_wrapper pt-3 pt-lg-0\">\n\n                            <table class=\"table table-borderless h-100 m-0\" t-att-data-ppg=\"ppg\" t-att-data-ppr=\"ppr\" t-att-data-default-sort=\"website.shop_default_sort\" t-att-data-name=\"grid_block_name\">\n\n                                <colgroup t-ignore=\"true\">\n                                    <col t-foreach=\"ppr\" t-as=\"p\"/>\n                                </colgroup>\n\n                                <tbody>\n\n                                    <tr t-foreach=\"bins\" t-as=\"tr_product\">\n\n                                        <t t-foreach=\"tr_product\" t-as=\"td_product\">\n\n                                            <t t-if=\"td_product\">\n\n                                                <td t-att-colspan=\"td_product['x'] != 1 and td_product['x']\" t-att-rowspan=\"td_product['y'] != 1 and td_product['y']\" t-attf-class=\"oe_product\" t-att-data-ribbon-id=\"td_product['ribbon'].id\" t-att-data-name=\"product_block_name\">\n\n                                                    <div t-attf-class=\"o_wsale_product_grid_wrapper position-relative h-100 o_wsale_product_grid_wrapper_#{td_product['x']}_#{td_product['y']}\">\n\n                                                        <t t-call=\"website_sale.products_item\">\n                                                            <t t-set=\"product\" t-value=\"td_product['product']\"/>\n                                                            <t t-set=\"template_price_vals\" t-value=\"get_product_prices(product)\"/>\n                                                            <t t-set=\"ribbon\" t-value=\"product._get_ribbon(price_vals=template_price_vals, auto_assign_ribbons=auto_assign_ribbons, variant=product_variants[product])\"/>\n                                                            <t t-set=\"design_field\" t-value=\"website.shop_opt_products_design_classes\"/>\n                                                            <t t-set=\"product_href\" t-value=\"product._get_product_url(category, product_query_params, grouped_attributes_values)\"/>\n                                                        </t>\n\n                                                    </div>\n                                                </td>\n                                            </t>\n\n                                            <td t-else=\"\"/>\n\n                                        </t>\n                                    </tr>\n\n                                </tbody>\n                            </table>\n                        </div>\n\n                        <div t-nocache=\"get the actual search\" t-else=\"\" class=\"text-center text-muted mt128 mb256\">\n\n                            <t t-if=\"not search\">\n\n                                <h3 class=\"mt8\">\n                                    Ningún producto definido\n                                </h3>\n\n                                <p t-if=\"category\">\n                                    No hay productos definidos en esta categoría.\n                                </p>\n\n                            </t>\n\n                            <t t-else=\"\">\n\n                                <h3 class=\"mt8\">\n                                    No hay resultados\n                                </h3>\n\n                                <p>\n                                    No hay resultados para\n                                    \"<strong t-esc=\"search\"/>\"\n\n                                    <t t-if=\"category\">\n                                        en la categoría\n                                        \"<strong t-esc=\"category.display_name\"/>\"\n                                    </t>.\n                                </p>\n\n                            </t>\n\n                            <p t-ignore=\"true\" groups=\"sales_team.group_sale_manager\">\n\n                                Haga clic en\n                                <i>\"Nuevo\"</i>\n                                en la esquina superior derecha para crear su\n                                primer producto.\n                            </p>\n                        </div>\n\n                        <div class=\"products_pager d-flex justify-content-center pt-5 pb-3\">\n                            <t t-call=\"website.pager\"/>\n                        </div>\n\n                    </div>\n                </div>\n\n                <t t-call=\"website_sale.o_wsale_offcanvas\"/>\n\n            </div>\n\n            <div class=\"oe_structure oe_empty oe_structure_not_nearest\" id=\"oe_structure_website_sale_products_2\"/>\n\n        </div>\n    </t>\n</t>", "pt_PT": "<t name=\"Products\" t-name=\"website_sale.products\">\n    <t t-call=\"website.layout\">\n        <t t-set=\"additional_title\">Loja</t>\n        <t t-set=\"grid_block_name\">Grelha</t>\n        <t t-set=\"product_block_name\">Produto</t>\n\n        <!-- Qweb variable defining the class suffix for navbar items -->\n        <t t-set=\"navClass\" t-valuef=\"light\"/>\n\n        <!-- Opciones activas -->\n        <t t-set=\"opt_wsale_categories\" t-value=\"is_view_active('website_sale.products_categories')\"/>\n        <t t-set=\"opt_wsale_attributes\" t-value=\"is_view_active('website_sale.products_attributes')\"/>\n        <t t-set=\"opt_wsale_filter_price\" t-value=\"is_view_active('website_sale.filter_products_price')\"/>\n        <t t-set=\"opt_wsale_filter_tags\" t-value=\"is_view_active('website_sale.filter_products_tags')\"/>\n\n        <t t-set=\"opt_wsale_categories_top\" t-value=\"is_view_active('website_sale.products_categories_top')\"/>\n        <t t-set=\"opt_wsale_attributes_top\" t-value=\"is_view_active('website_sale.products_attributes_top')\"/>\n\n        <t t-set=\"website_sale_pricelists\" t-value=\"website.get_pricelist_available(show_visible=True)\"/>\n        <t t-set=\"website_sale_sortable\" t-value=\"website._get_product_sort_mapping()\"/>\n\n        <t t-set=\"hasLeftColumn\" t-value=\"opt_wsale_categories or opt_wsale_attributes\"/>\n\n        <t t-set=\"isFilteringByPrice\" t-if=\"opt_wsale_filter_price\" t-value=\"float_round(available_min_price, 2) != float_round(min_price, 2) or float_round(available_max_price, 2) != float_round(max_price, 2)\"/>\n\n        <t t-set=\"hasPricelistDropdown\" t-value=\"website_sale_pricelists and len(website_sale_pricelists)&gt;1\"/>\n\n        <t t-set=\"isSortingBy\" t-value=\"[sort for sort in website_sale_sortable if sort[0] == request.params.get('order', '')]\"/>\n\n        <div id=\"wrap\" class=\"js_sale o_wsale_products_page\">\n\n            <!-- ===================================================== -->\n            <!-- BANNER SUPERIOR: CONDICIONES DE COMPRA -->\n            <!-- ===================================================== -->\n            <section class=\"position-relative overflow-hidden o_colored_level\" data-name=\"Banner condiciones de compra\" style=\"background: linear-gradient(100deg, rgba(3, 22, 52, 0.99) 0%, rgba(6, 36, 76, 0.97) 58%, rgba(10, 48, 91, 0.94) 100%); border-bottom: 4px solid rgb(237, 37, 36);\">\n\n                \n                <div class=\"position-absolute\" style=\"                         width: 290px;                         height: 290px;                         top: -165px;                         right: 8%;                         border-radius: 50%;                         border: 1px solid rgba(255,255,255,0.10);                         background-color: rgba(255,255,255,0.025);                         pointer-events: none;                      \">\n                </div>\n\n                <div class=\"position-absolute\" style=\"                         width: 165px;                         height: 165px;                         right: 18%;                         bottom: -105px;                         border-radius: 50%;                         border: 1px solid rgba(237,37,36,0.20);                         background-color: rgba(237,37,36,0.035);                         pointer-events: none;                      \">\n                </div>\n\n                <div class=\"container position-relative py-3 py-lg-4\" style=\"                         z-index: 2;                         max-width: 1220px;                      \">\n\n                    <div class=\"row align-items-center g-3\">\n\n                        \n                        <div class=\"col-auto d-none d-md-block\">\n\n                            <div class=\"d-flex align-items-center justify-content-center\" style=\"                                     width: 64px;                                     height: 64px;                                     border-radius: 50%;                                     color: #ffffff;                                     border: 1px solid rgba(255,255,255,0.28);                                     background-color: rgba(255,255,255,0.08);                                  \">\n\n                                <i class=\"fa fa-file-text-o\" style=\"font-size: 1.75rem;\" aria-hidden=\"true\">​</i>\n                            </div>\n\n                        </div>\n\n                        \n                        <div class=\"col\">\n\n                            <div class=\"d-flex align-items-center mb-1\">\n\n                                <span class=\"me-2\" style=\"                                         display: inline-block;                                         width: 28px;                                         height: 3px;                                         border-radius: 5px;                                         background-color: #ed2524;                                       \">\n                                </span>\n\n                                <span style=\"                                         color: #ed2524;                                         font-size: 0.82rem;                                         font-weight: 800;                                         letter-spacing: 0.08em;                                         text-transform: uppercase;                                       \">\n                                    Información importante\n                                </span>\n\n                            </div>\n\n                            <h2 class=\"text-white mb-1\" style=\"                                     font-size: clamp(1.25rem, 2vw, 1.7rem);                                     font-weight: 750;                                     line-height: 1.25;                                 \">\n                                Consulta nuestras condiciones de compra\n                            </h2>\n\n                            <p class=\"mb-0\" style=\"                                     max-width: 760px;                                     color: rgba(255,255,255,0.83);                                     font-size: 0.95rem;                                     line-height: 1.55;                                \">\n                                Revisa la información sobre precios, formas de pago,\n                                gastos de envío, reclamaciones, devoluciones y protección\n                                de datos antes de finalizar tu pedido.\n                            </p>\n\n                        </div>\n\n                        \n                        <div class=\"col-12 col-lg-auto o_colored_level\">\n\n                            <a href=\"/condiciones-de-compra\" class=\"d-inline-flex align-items-center justify-content-center px-4 py-2 btn btn-custom\" style=\"                                     min-width: 220px;                                     min-height: 46px;                                     border: 2px solid #ed2524;                                     border-radius: 9px;                                     background-color: #ed2524;                                     font-size: 0.95rem;                                     font-weight: 700;                                     box-shadow: 0 8px 22px rgba(237,37,36,0.24);                                \" data-bs-original-title=\"\" title=\"\">\n\n                                Ver condiciones de compra\n\n                                <i class=\"fa fa-arrow-right ms-2\" aria-hidden=\"true\"/>\n                            </a>\n\n                        </div>\n\n                    </div>\n                </div>\n            </section>\n\n            <!-- Área editable superior original -->\n            <div class=\"oe_structure oe_empty oe_structure_not_nearest\" id=\"oe_structure_website_sale_products_1\"/>\n\n            <div class=\"container oe_website_sale pt-2\">\n\n                <div class=\"row o_wsale_products_main_row align-items-start flex-nowrap\">\n\n                    <aside t-if=\"hasLeftColumn\" id=\"products_grid_before\" class=\"d-none d-lg-block position-sticky col-3 px-3 clearfix\">\n\n                        <div class=\"o_wsale_products_grid_before_rail vh-100 ms-n2 mt-n2 pt-2 pe-lg-2 pb-lg-5 ps-2 overflow-y-scroll\">\n\n                            <div t-if=\"opt_wsale_categories\" class=\"products_categories mb-3\">\n                                <t t-call=\"website_sale.products_categories_list\"/>\n                            </div>\n\n                            <div class=\"products_attributes_filters\"/>\n\n                            <t t-if=\"opt_wsale_filter_price and opt_wsale_attributes\" t-call=\"website_sale.filter_products_price\"/>\n\n                        </div>\n                    </aside>\n\n                    <div id=\"products_grid\" t-attf-class=\"#{'o_wsale_layout_list' if layout_mode == 'list' else ''} {{'col-lg-9' if hasLeftColumn else 'col-12'}}\">\n\n                        <t t-call=\"website_sale.products_breadcrumb\">\n                            <t t-set=\"_classes\" t-valuef=\"d-none d-lg-flex w-100 p-0 small\"/>\n                        </t>\n\n                        <div class=\"products_header btn-toolbar flex-nowrap align-items-center justify-content-between gap-3 mb-3\">\n\n                            <t t-if=\"is_view_active('website_sale.search')\" t-call=\"website_sale.search\">\n\n                                <t t-set=\"search\" t-value=\"original_search or search\"/>\n\n                                <t t-set=\"_form_classes\" t-valuef=\"d-lg-inline {{'d-inline' if not category else 'd-none'}}\"/>\n                            </t>\n\n                            <t t-call=\"website_sale.pricelist_list\" t-cache=\"pricelist\">\n\n                                <t t-set=\"_classes\" t-valuef=\"d-none d-lg-inline\"/>\n                            </t>\n\n                            <t t-if=\"is_view_active('website_sale.sort')\" t-call=\"website_sale.sort\">\n\n                                <t t-set=\"_classes\" t-valuef=\"d-none me-auto d-lg-inline-block\"/>\n                            </t>\n\n                            <div t-if=\"category\" class=\"d-flex align-items-center d-lg-none me-auto\">\n\n                                <t t-if=\"not category.parent_id\" t-set=\"backUrl\" t-valuef=\"/shop\"/>\n\n                                <t t-else=\"\" t-set=\"backUrl\" t-value=\"keep('/shop/category/' + slug(category.parent_id), category=0)\"/>\n\n                                <a t-attf-class=\"btn btn-{{navClass}} me-2\" t-att-href=\"category.parent_id and keep('/shop/category/' + slug(category.parent_id), category=0) or '/shop'\">\n\n                                    <i class=\"fa fa-angle-left\"/>\n                                </a>\n\n                                <h4 t-out=\"category.name\" class=\"mb-0 me-auto\"/>\n                            </div>\n\n                            \n\n                            <button t-if=\"is_view_active('website_sale.sort') or opt_wsale_categories or opt_wsale_attributes or opt_wsale_attributes_top\" t-attf-class=\"btn btn-{{navClass}} position-relative {{not opt_wsale_attributes_top and 'd-lg-none'}}\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#o_wsale_offcanvas\">\n\n                                <i class=\"fa fa-sliders\"/>\n\n                                <span t-if=\"isFilteringByPrice or attrib_set or tags\" t-attf-class=\"position-absolute top-0 start-100 translate-middle border border-{{navClass}} rounded-circle bg-danger p-1\">\n\n                                    <span class=\"visually-hidden\">filtros ativos</span>\n                                </span>\n                            </button>\n\n                        </div>\n\n                        <t t-if=\"opt_wsale_categories_top\" t-call=\"website_sale.filmstrip_categories\"/>\n\n                        <div t-if=\"original_search and products\" class=\"alert alert-warning mt8\">\n\n                            Nenhum resultado encontrado para '<span t-esc=\"original_search\"/>'. A mostrar resultados para '<span t-esc=\"search\"/>\".\n                        </div>\n\n                        <t t-if=\"category\">\n\n                            <t t-set=\"editor_msg\">\n                                Arraste blocos de construção para aqui para personalizar o cabeçalho para \"<t t-esc=\"category.name\"/>\" categoria.\n                            </t>\n\n                            <div class=\"mb16\" id=\"category_header\" t-att-data-editor-message=\"editor_msg\" t-field=\"category.website_description\"/>\n                        </t>\n\n                        <div t-if=\"products\" class=\"o_wsale_products_grid_table_wrapper pt-3 pt-lg-0\">\n\n                            <table class=\"table table-borderless h-100 m-0\" t-att-data-ppg=\"ppg\" t-att-data-ppr=\"ppr\" t-att-data-default-sort=\"website.shop_default_sort\" t-att-data-name=\"grid_block_name\">\n\n                                <colgroup t-ignore=\"true\">\n                                    <col t-foreach=\"ppr\" t-as=\"p\"/>\n                                </colgroup>\n\n                                <tbody>\n\n                                    <tr t-foreach=\"bins\" t-as=\"tr_product\">\n\n                                        <t t-foreach=\"tr_product\" t-as=\"td_product\">\n\n                                            <t t-if=\"td_product\">\n\n                                                <td t-att-colspan=\"td_product['x'] != 1 and td_product['x']\" t-att-rowspan=\"td_product['y'] != 1 and td_product['y']\" t-attf-class=\"oe_product\" t-att-data-ribbon-id=\"td_product['ribbon'].id\" t-att-data-name=\"product_block_name\">\n\n                                                    <div t-attf-class=\"o_wsale_product_grid_wrapper position-relative h-100 o_wsale_product_grid_wrapper_#{td_product['x']}_#{td_product['y']}\">\n\n                                                        <t t-call=\"website_sale.products_item\">\n                                                            <t t-set=\"product\" t-value=\"td_product['product']\"/>\n                                                            <t t-set=\"template_price_vals\" t-value=\"get_product_prices(product)\"/>\n                                                            <t t-set=\"ribbon\" t-value=\"product._get_ribbon(price_vals=template_price_vals, auto_assign_ribbons=auto_assign_ribbons, variant=product_variants[product])\"/>\n                                                            <t t-set=\"design_field\" t-value=\"website.shop_opt_products_design_classes\"/>\n                                                            <t t-set=\"product_href\" t-value=\"product._get_product_url(category, product_query_params, grouped_attributes_values)\"/>\n                                                        </t>\n\n                                                    </div>\n                                                </td>\n                                            </t>\n\n                                            <td t-else=\"\"/>\n\n                                        </t>\n                                    </tr>\n\n                                </tbody>\n                            </table>\n                        </div>\n\n                        <div t-nocache=\"get the actual search\" t-else=\"\" class=\"text-center text-muted mt128 mb256\">\n\n                            <t t-if=\"not search\">\n\n                                <h3 class=\"mt8\">\n                                    Nenhum artigo definido\n                                </h3>\n\n                                <p t-if=\"category\">\n                                    Nenhum artigo definido nesta categoria\n                                </p>\n\n                            </t>\n\n                            <t t-else=\"\">\n\n                                <h3 class=\"mt8\">\n                                    Nenhum resultado\n                                </h3>\n\n                                <p>\n                                    Nenhum resultado para \"<strong t-esc=\"search\"/>\"\n\n                                    <t t-if=\"category\">\n                                        na categoria \"<strong t-esc=\"category.display_name\"/>\"\n                                    </t>.\n                                </p>\n\n                            </t>\n\n                            <p t-ignore=\"true\" groups=\"sales_team.group_sale_manager\">\n\n                                Clique em <i>'Novo'</i> no canto superior direito para criar o seu primeiro produto.\n                            </p>\n                        </div>\n\n                        <div class=\"products_pager d-flex justify-content-center pt-5 pb-3\">\n                            <t t-call=\"website.pager\"/>\n                        </div>\n\n                    </div>\n                </div>\n\n                <t t-call=\"website_sale.o_wsale_offcanvas\"/>\n\n            </div>\n\n            <div class=\"oe_structure oe_empty oe_structure_not_nearest\" id=\"oe_structure_website_sale_products_2\"/>\n\n        </div>\n    </t>\n</t>"}$new$::jsonb THEN
